"""TOML configuration loader for Pylama."""

from __future__ import annotations

from typing import Any, Dict

from pylama.libs.inirama import Namespace as _Namespace

try:
    import tomllib as _toml
except ImportError:  # pragma: no cover
    try:
        import tomli as _toml  # type: ignore
    except ImportError:  # pragma: no cover
        import toml as _toml  # type: ignore


def _loads(source: str) -> Dict[str, Any]:
    return _toml.loads(source)


class Namespace(_Namespace):
    """Inirama-style wrapper for TOML config files."""

    def parse(self, source: str, update: bool = True, **params):
        content = _loads(source)
        tool = content.get("tool", {})
        pylama = dict(tool.get("pylama", {}))
        linters = pylama.pop("linter", {})
        files = pylama.pop("files", [])

        for name, value in pylama.items():
            self["pylama"][name] = value

        for linter_name, options in linters.items():
            for name, value in options.items():
                self[f"pylama:{linter_name}"][name] = value

        for file_options in files:
            if not isinstance(file_options, dict):
                continue
            entry = dict(file_options)
            path = entry.pop("path", None)
            if path is None:
                continue
            for name, value in entry.items():
                self[f"pylama:{path}"][name] = value

