"""CLI entry points and path scanning."""

from __future__ import annotations

import sys
import warnings
from json import dumps
from os import path as op
from os import walk
from pathlib import Path
from typing import List, Optional

from pylama import LOGGER
from pylama.check_async import check_async
from pylama.config import CURDIR, Namespace, parse_options, setup_logger
from pylama.core import run
from pylama.errors import Error
from pylama.utils import read_stdin

DEFAULT_FORMAT = "{filename}:{lnum}:{col} [{etype}] {number} {message} [{source}]"
MESSAGE_FORMATS = {
    "pylint": "{filename}:{lnum}: [{etype}] {number} {message} [{source}]",
    "pycodestyle": "{filename}:{lnum}:{col} {number} {message} [{source}]",
    "parsable": DEFAULT_FORMAT,
    "pydocstyle": "{filename}:{lnum} {number} {message} [{source}]",
}


def check_paths(
    paths: Optional[List[str]],
    options: Namespace,
    code: str = None,
    rootdir: Path = None,
) -> List[Error]:
    """Check the given files or directories."""
    paths = paths or options.paths
    if not paths:
        return []
    if code is None:
        candidates: List[str] = []
        for path in paths:
            if not op.exists(path):
                continue
            if not op.isdir(path):
                candidates.append(op.abspath(path))
                continue
            for current_root, _, files in walk(path):
                candidates.extend(op.relpath(op.join(current_root, name), CURDIR) for name in files)
    else:
        candidates = [paths[0]]
    if not candidates:
        return []
    if rootdir is None:
        first = candidates[0]
        rootdir = Path(first if op.isdir(first) else op.dirname(first) or ".")
    candidates = [path for path in candidates if path.endswith(".py")]
    if options.concurrent:
        return check_async(candidates, code=code, options=options, rootdir=rootdir)
    errors: List[Error] = []
    for path in candidates:
        errors.extend(run(path=path, code=code, rootdir=rootdir, options=options))
    return errors


def check_path(
    options: Namespace,
    rootdir: str = None,
    candidates: List[str] = None,
    code: str = None,
) -> List[Error]:
    """Backwards-compatible alias for older callers."""
    warnings.warn(
        "pylama.main.check_path is deprecated and will be removed in a future release",
        DeprecationWarning,
    )
    return check_paths(
        candidates,
        code=code,
        options=options,
        rootdir=Path(rootdir) if rootdir else None,
    )


def shell(args: List[str] = None, error: bool = True):
    """CLI entry point."""
    if args is None:
        args = sys.argv[1:]
    options = parse_options(args)
    setup_logger(options)
    LOGGER.info(options)
    if options.hook:
        from pylama.hook import install_hook

        for path in options.paths:
            return install_hook(path)
    if options.from_stdin and not options.paths:
        LOGGER.error("--from-stdin requires a filename")
        if error:
            sys.exit(1)
        return []
    errors = check_paths(
        options.paths,
        code=read_stdin() if options.from_stdin else None,
        options=options,
        rootdir=CURDIR,
    )
    display_errors(errors, options)
    if error:
        sys.exit(int(bool(errors)))
    return errors


def display_errors(errors: List[Error], options: Namespace):
    """Format and output the given errors."""
    if options.format == "json":
        LOGGER.warning(dumps([error.to_dict() for error in errors]))
        return
    pattern = MESSAGE_FORMATS.get(options.format, DEFAULT_FORMAT)
    for error in errors:
        LOGGER.warning(error.format(pattern))


if __name__ == "__main__":
    shell()

