"""Minimal bundled Inirama implementation used by Pylama."""

from __future__ import annotations

import io
import logging
import re
from collections import OrderedDict

__version__ = "0.8.0"
__project__ = "Inirama"
__author__ = "Kirill Klenov <horneds@gmail.com>"
__license__ = "BSD"

NS_LOGGER = logging.getLogger("inirama")


class Scanner:
    """Split a source string into tokens."""

    patterns = []
    ignore = []

    def __init__(self, source, ignore=None, patterns=None):
        self.reset(source)
        if patterns:
            self.patterns = []
            for name, pattern in patterns:
                self.patterns.append((name, re.compile(pattern)))
        if ignore:
            self.ignore = ignore

    def reset(self, source):
        """Reset scanner state."""
        self.tokens = []
        self.source = source
        self.pos = 0

    def scan(self):
        """Scan the current source."""
        self.pre_scan()
        end = len(self.source)
        while self.pos < end:
            best_pat = None
            best_pat_len = 0
            for pattern_name, regexp in self.patterns:
                match = regexp.match(self.source, self.pos)
                if match:
                    best_pat = pattern_name
                    best_pat_len = len(match.group(0))
                    break
            if best_pat is None:
                raise SyntaxError(
                    f"SyntaxError[@char {self.pos}: Bad token.]"
                )
            if best_pat in self.ignore:
                self.pos += best_pat_len
                continue
            token = (
                best_pat,
                self.source[self.pos : self.pos + best_pat_len],
                self.pos,
                self.pos + best_pat_len,
            )
            self.pos = token[-1]
            self.tokens.append(token)

    def pre_scan(self):
        """Prepare the source before scanning."""

    def __repr__(self):
        parts = ",".join(f"{name}({start}:{end})" for name, _, start, end in self.tokens[-5:])
        return f"<Scanner: {parts}>"


class INIScanner(Scanner):
    """INI-specific scanner."""

    patterns = [
        ("SECTION", re.compile(r"\[[^]]+\]")),
        ("IGNORE", re.compile(r"[ \r\t\n]+")),
        ("COMMENT", re.compile(r"[;#].*")),
        ("KEY_VALUE", re.compile(r"[^=\s]+\s*[:=].*")),
        ("CONTINUATION", re.compile(r".*")),
    ]
    ignore = ["IGNORE"]

    def pre_scan(self):
        self.source = re.compile(r"\\\n[\t ]+").sub("", self.source)


undefined = object()


class Section(OrderedDict):
    """Ordered mapping for one INI section."""

    def __init__(self, namespace, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.namespace = namespace

    def __setitem__(self, name, value):
        value = str(value)
        if value.isdigit():
            value = int(value)
        super().__setitem__(name, value)


class InterpolationSection(Section):
    """Section with string interpolation support."""

    var_re = re.compile(r"{([^}]+)}")

    def get(self, name, default=None):
        if name in self:
            return self[name]
        return default

    def __interpolate__(self, match):
        key = match.group(1).strip()
        try:
            return self.namespace.default.get(key) or self[key]
        except KeyError:
            return ""

    def __getitem__(self, name, raw=False):
        value = super().__getitem__(name)
        if not raw and isinstance(value, str):
            sample = undefined
            while sample != value:
                try:
                    sample, value = value, self.var_re.sub(self.__interpolate__, value)
                except RuntimeError as exc:
                    message = f"Interpolation failed: {name}"
                    NS_LOGGER.error(message)
                    raise ValueError(message) from exc
        return value

    def iteritems(self, raw=False):
        for key in self:
            yield key, self.__getitem__(key, raw=raw)

    items = iteritems


class Namespace:
    """INI namespace made of named sections."""

    default_section = "DEFAULT"
    silent_read = True
    section_type = Section

    def __init__(self, **default_items):
        self.sections = OrderedDict()
        for key, value in default_items.items():
            self[self.default_section][key] = value

    @property
    def default(self):
        return self.sections.get(self.default_section, {})

    def read(self, *files, **params):
        for path in files:
            try:
                with io.open(path, encoding="utf-8") as source:
                    NS_LOGGER.info("Read from `%s`", source.name)
                    self.parse(source.read(), **params)
            except (IOError, OSError, TypeError, SyntaxError, io.UnsupportedOperation):
                if not self.silent_read:
                    NS_LOGGER.error("Reading error `%s`", path)
                    raise

    def write(self, file_or_path):
        if isinstance(file_or_path, str):
            file_or_path = io.open(file_or_path, "w", encoding="utf-8")
        if not hasattr(file_or_path, "write"):
            raise AttributeError(f"Wrong type of file: {type(file_or_path)}")
        NS_LOGGER.info("Write to `%s`", file_or_path.name)
        for section in self.sections:
            file_or_path.write(f"[{section}]\n")
            for key, value in self[section].items():
                file_or_path.write(f"{key:15}= {value}\n")
            file_or_path.write("\n")
        file_or_path.close()

    def parse(self, source, update=True, **_):
        scanner = INIScanner(source)
        scanner.scan()
        section = self.default_section
        name = None
        for token_name, token_value, token_start, _ in scanner.tokens:
            if token_name == "KEY_VALUE":
                name, value = re.split("[=:]", token_value, 1)
                name, value = name.strip(), value.strip()
                if not update and name in self[section]:
                    continue
                self[section][name] = value
            elif token_name == "SECTION":
                section = token_value.strip("[]")
            elif token_name == "CONTINUATION":
                if not name:
                    raise SyntaxError(
                        f"SyntaxError[@char {token_start}: Bad continuation.]"
                    )
                self[section][name] += "\n" + token_value.strip()

    def __getitem__(self, name):
        if name not in self.sections:
            self.sections[name] = self.section_type(self)
        return self.sections[name]

    def __contains__(self, name):
        return name in self.sections

    def __repr__(self):
        return f"<Namespace: {self.sections}>"


class InterpolationNamespace(Namespace):
    """Namespace with interpolation-aware sections."""

    section_type = InterpolationSection

