"""Argument and configuration parsing for Pylama."""

from __future__ import annotations

import fnmatch
import logging
import os
import re
import sys
from argparse import ArgumentParser, Namespace
from pathlib import Path
from typing import Any, Collection, Dict, List, Optional, Set, Union

from pylama import LOGGER, __version__
from pylama.libs import inirama
from pylama.lint import LINTERS

try:
    from pylama import config_toml

    CONFIG_FILES = ["pylama.ini", "pyproject.toml", "setup.cfg", "tox.ini", "pytest.ini"]
except ImportError:  # pragma: no cover
    CONFIG_FILES = ["pylama.ini", "setup.cfg", "tox.ini", "pytest.ini"]

DEFAULT_LINTERS = ("pycodestyle", "pyflakes", "mccabe")

CURDIR = Path.cwd()
HOMECFG = Path.home() / ".pylama.ini"
DEFAULT_SECTION = "pylama"

LOGGER.propagate = False
STREAM = logging.StreamHandler(sys.stdout)
if STREAM not in LOGGER.handlers:
    LOGGER.addHandler(STREAM)


class _Default:
    def __init__(self, value=None):
        self.value = value

    def __str__(self):
        return str(self.value)

    def __repr__(self):
        return f"<_Default [{self.value}]>"


def split_csp_str(val: Union[Collection[str], str, None]) -> Set[str]:
    """Split comma-separated strings or collections into a set."""
    if not val:
        return set()
    if isinstance(val, str):
        val = val.strip().split(",")
    return {str(item) for item in val if item}


def parse_skip_patterns(val: Union[Collection[str], str, None]) -> List[re.Pattern]:
    if not val:
        return []
    if isinstance(val, str):
        val = [item for item in val.split(",") if item]
    return [re.compile(fnmatch.translate(fix_pathname_sep(str(item)))) for item in val]


def prepare_sorter(val: Union[Collection[str], str, None]) -> Optional[Dict[str, int]]:
    if val:
        types = split_csp_str(val)
        return {value: index for index, value in enumerate(types, 1)}
    return None


def parse_linters(linters: Union[Collection[str], str, None]) -> List[str]:
    """Keep only linters supported by the current installation."""
    return [name for name in split_csp_str(linters) if name in LINTERS]


def get_default_config_file(rootdir: Path = None) -> Optional[str]:
    """Search for a readable configuration file."""
    if rootdir is None:
        return DEFAULT_CONFIG_FILE
    for filename in CONFIG_FILES:
        path = rootdir / filename
        if path.is_file() and os.access(path, os.R_OK):
            return path.as_posix()
    return None


DEFAULT_CONFIG_FILE = get_default_config_file(CURDIR)


def setup_parser() -> ArgumentParser:
    """Create and setup the command-line parser."""
    parser = ArgumentParser(description="Code audit tool for python.")
    parser.add_argument(
        "paths",
        nargs="*",
        default=_Default([CURDIR.as_posix()]),
        help="Paths to files or directories for code check.",
    )
    parser.add_argument("--version", action="version", version="%(prog)s " + __version__)
