def _env_overrides() -> Dict[str, Any]:
    mapping = {
        "linters": "PYLAMA_LINTERS",
        "ignore": "PYLAMA_IGNORE",
        "select": "PYLAMA_SELECT",
        "skip": "PYLAMA_SKIP",
        "format": "PYLAMA_FORMAT",
        "abspath": "PYLAMA_ABSPATH",
        "max_line_length": "PYLAMA_MAX_LINE_LENGTH",
        "max_complexity": "PYLAMA_MAX_COMPLEXITY",
        "concurrent": "PYLAMA_CONCURRENT",
        "verbose": "PYLAMA_VERBOSE",
    }
    result = {}
    for option, env_name in mapping.items():
        value = os.environ.get(env_name)
        if value is not None:
            result[option] = value
    return result


def parse_options(
    args: List[str] = None,
    config: bool = True,
    rootdir: Path = CURDIR,
    **overrides,
) -> Namespace:
    """Parse CLI arguments and configuration files."""
    parser = setup_parser()
    actions = {action.dest: action for action in parser._actions}  # pylint: disable=protected-access
    options = parser.parse_args(args or [])
    options.file_params = {}
    options.linters_params = {}

    for opt, value in _env_overrides().items():
        if isinstance(getattr(options, opt, None), _Default):
            setattr(options, opt, _Default(value))

    if config:
        cfg = get_config(options.options, rootdir=rootdir)
        for opt, value in cfg.default.items():
            LOGGER.info("Find option %s (%s)", opt, value)
            passed_value = getattr(options, opt, _Default())
            if isinstance(passed_value, _Default):
                if opt == "paths" and isinstance(value, str):
                    value = value.split()
                if opt == "skip":
                    value = fix_pathname_sep(value) if isinstance(value, str) else value
                setattr(options, opt, _Default(value))

        for name, cfg_options in cfg.sections.items():
            if name == cfg.default_section:
                continue
            if name.startswith("pylama"):
                name = name[7:]
            if name in LINTERS:
                options.linters_params[name] = dict(cfg_options)
                continue
            mask = re.compile(fnmatch.translate(fix_pathname_sep(name)))
            options.file_params[mask] = dict(cfg_options)

    for opt, value in overrides.items():
        setattr(options, opt, process_value(actions, opt, value))

    for name, value in list(options.__dict__.items()):
        if isinstance(value, _Default):
            setattr(options, name, process_value(actions, name, value.value))

    if options.concurrent and "pylint" in options.linters:
        LOGGER.warning("Can't parse code asynchronously with pylint enabled.")
        options.concurrent = False
    return options


def process_value(actions: Dict, name: str, value: Any) -> Any:
    """Normalize option values using parser action types."""
    action = actions.get(name)
    if not action:
        return value
    if callable(action.type):
        return action.type(value)
    if action.const is not None and isinstance(value, str):
        return bool(int(value))
    return value


def get_config(user_path: str = None, rootdir: Path = None) -> inirama.Namespace:
    """Load configuration from the discovered config file."""
    cfg_path = user_path or os.environ.get("PYLAMA_CONFIG") or get_default_config_file(rootdir)
    if not cfg_path and HOMECFG.exists():
        cfg_path = HOMECFG.as_posix()
    if cfg_path:
        LOGGER.info("Read config: %s", cfg_path)
        if cfg_path.endswith(".toml"):
            return get_config_toml(cfg_path)
        return get_config_ini(cfg_path)
    return inirama.Namespace()


def get_config_ini(ini_path: str) -> inirama.Namespace:
    config = inirama.Namespace()
    config.default_section = DEFAULT_SECTION
    config.read(ini_path)
    return config


def get_config_toml(toml_path: str) -> inirama.Namespace:
    config = config_toml.Namespace()
    config.default_section = DEFAULT_SECTION
    config.read(toml_path)
    return config


def setup_logger(options: Namespace):
    """Configure the package logger."""
    LOGGER.setLevel(logging.INFO if options.verbose else logging.WARN)
    if options.report:
        if STREAM in LOGGER.handlers:
            LOGGER.removeHandler(STREAM)
        LOGGER.addHandler(logging.FileHandler(options.report, mode="w"))
    if options.options:
        LOGGER.info("Try to read configuration from: %r", options.options)


def fix_pathname_sep(val: str) -> str:
    """Normalize path separators across platforms."""
    return val.replace(os.altsep or "\\", os.sep)

