from __future__ import annotations

from argparse import ArgumentParser
from importlib import import_module
from pathlib import Path
from pkgutil import walk_packages
from typing import TYPE_CHECKING, Any, Dict, List, Optional, Type

try:
    from pkg_resources import iter_entry_points
except ImportError:  # pragma: no cover
    from importlib.metadata import entry_points

    def iter_entry_points(group):
        return entry_points(group=group)

LINTERS: Dict[str, Type["LinterV2"]] = {}

if TYPE_CHECKING:
    from pylama.context import RunContext


class LinterMeta(type):
    """Register linter subclasses as they are defined."""

    def __new__(mcs, name, bases, params):
        cls: Type["LinterV2"] = super().__new__(mcs, name, bases, params)
        if cls.name is not None:
            LINTERS[cls.name] = cls
        return cls


class Linter(metaclass=LinterMeta):
    """Abstract class for a linter plugin."""

    name: Optional[str] = None

    @classmethod
    def add_args(cls, _: ArgumentParser):
        """Register CLI arguments for this linter."""

    def allow(self, path: Path) -> bool:
        """Return whether the linter can handle the given path."""
        return path.suffix == ".py"

    def run(self, _path: str, **_meta) -> List[Dict[str, Any]]:
        """Legacy linter interface."""
        return []


class LinterV2(Linter):
    """Context-based linter interface."""

    def run_check(self, ctx: "RunContext"):
        """Run lint checks against the given context."""


for _, module_name, _ in walk_packages([str(Path(__file__).parent)]):
    try:
        import_module(f"{__name__}.{module_name}")
    except ImportError:
        pass

for entry in iter_entry_points("pylama.linter"):
    if entry.name not in LINTERS:
        try:
            LINTERS[entry.name] = entry.load()
        except ImportError:
            pass

